m_SettingJson:
{
  "version": 2,
  "system": {
    "enabled": true,
    "advanced": true,
    "include": ["display", "quality", "audio", "performance"]
  },
  "tabs": [
    {
      "id": "project.demo",
      "label": "项目示例",
      "order": 100,
      "kind": "project",
      "groups": [
        {
          "id": "look",
          "label": "外观",
          "description": "改完后点底部「应用」。中间方块会马上变。",
          "items": [
            {
              "type": "info",
              "key": "project.help",
              "label": "怎么看效果",
              "description": "阴影距离看右侧由近到远的方块影子。阴影质量看近处影子硬软。LOD 偏移看左侧模型从圆球换成方块。各向异性过滤看地面斜向格子。主音量听循环提示音。渲染比例会让整屏变糊或变清晰。"
            },
            {
              "key": "project.color",
              "type": "enum",
              "label": "方块颜色",
              "description": "中间方块的颜色",
              "default": "white",
              "options": [
                { "value": "white", "label": "白" },
                { "value": "red", "label": "红" },
                { "value": "green", "label": "绿" },
                { "value": "blue", "label": "蓝" },
                { "value": "yellow", "label": "黄" }
              ]
            },
            {
              "key": "project.spinSpeed",
              "type": "float",
              "label": "转速",
              "description": "方块每秒转多少度",
              "default": 45,
              "min": 0,
              "max": 240,
              "step": 1,
              "unit": "°/s"
            },
            {
              "key": "project.scale",
              "type": "float",
              "label": "缩放",
              "default": 1,
              "min": 0.4,
              "max": 2.5,
              "step": 0.05
            },
            {
              "key": "project.caption",
              "type": "string",
              "label": "标题",
              "description": "显示在画面顶部",
              "default": "设置演示"
            }
          ]
        },
        {
          "id": "marker",
          "label": "标记",
          "description": "标记关掉后，高度这一项会隐藏。",
          "items": [
            {
              "key": "project.showMarker",
              "type": "bool",
              "label": "显示标记",
              "default": true
            },
            {
              "key": "project.markerHeight",
              "type": "float",
              "label": "标记高度",
              "default": 2.2,
              "min": 0.4,
              "max": 6,
              "step": 0.1,
              "unit": "m",
              "visibleIf": "project.showMarker=true"
            }
          ]
        },
        {
          "id": "lights",
          "label": "附加光",
          "description": "关掉附加光后，强度不能拖。",
          "items": [
            {
              "key": "project.extraLights",
              "type": "bool",
              "label": "附加光",
              "default": true
            },
            {
              "key": "project.lightIntensity",
              "type": "float",
              "label": "附加光强度",
              "default": 1.5,
              "min": 0,
              "max": 4,
              "step": 0.05,
              "enabledIf": "project.extraLights=true"
            }
          ]
        },
        {
          "id": "actions",
          "label": "操作",
          "items": [
            {
              "key": "project.pulse",
              "type": "button",
              "label": "跳动一下",
              "description": "让中间方块短暂变大",
              "buttonAction": "pulseSubject"
            }
          ]
        }
      ]
    }
  ]
}

